package pagos;
import static org.junit.jupiter.api.Assertions.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.HexFormat;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.junit.jupiter.api.Test;
class ValidadorFirmaMercadoPagoTest {@Test void validaManifestOficialYRechazaReplay()throws Exception{Clock c=Clock.fixed(Instant.ofEpochMilli(1760436000000L),ZoneOffset.UTC);String ts="1760436000000",id="123",rid="req-1",secret="firma";String manifest="id:"+id+";request-id:"+rid+";ts:"+ts+";";Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String v=HexFormat.of().formatHex(mac.doFinal(manifest.getBytes(StandardCharsets.UTF_8)));var f=new ValidadorFirmaMercadoPago(secret,c,300);assertTrue(f.validar("ts="+ts+",v1="+v,rid,id));assertFalse(f.validar("ts=1,v1="+v,rid,id));assertFalse(f.validar("ts="+ts+",v1=00",rid,id));}}
